CREATE TABLE IF NOT EXISTS customers (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name       text NOT NULL,
    email      text NOT NULL,
    city       text,                         -- NULL allowed: may be unknown
    created_at timestamptz NOT NULL DEFAULT now()  -- date and time it was added
);

-- Change the table later
ALTER TABLE customers ADD COLUMN phone text;
ALTER TABLE customers RENAME COLUMN phone TO phone_number;
ALTER TABLE customers ALTER COLUMN city SET DEFAULT 'unknown';
ALTER TABLE customers DROP COLUMN phone_number;

-- See a table's columns in psql:  \d customers

DROP TABLE IF EXISTS scratch_import;

CREATE INDEX orders_customer_id_idx ON orders (customer_id);

-- Serves equality on customer_id plus ordering by ordered_at
CREATE INDEX orders_customer_time_idx ON orders (customer_id, ordered_at);

-- Uses orders_customer_time_idx: no sort needed, stops after 10 rows
SELECT id, total FROM orders
WHERE customer_id = 2
ORDER BY ordered_at DESC
LIMIT 10;

-- Cannot use the index well: leading column is unconstrained
SELECT id FROM orders WHERE ordered_at > now() - interval '7 days';

-- Production-safe build that does not block writes
CREATE INDEX CONCURRENTLY customers_email_idx ON customers (email);

-- Which indexes exist?  In psql:  \di

BEGIN;
INSERT INTO orders (customer_id, total) VALUES (4, 19.50)
RETURNING id;                                   -- 106
INSERT INTO order_items (order_id, product_id, quantity, unit_price)
VALUES (106, 2, 1, 19.50);
COMMIT;                                         -- both rows, or neither

-- Recovering from an expected failure with a savepoint
BEGIN;
UPDATE customers SET city = 'Berlin' WHERE id = 4;
SAVEPOINT before_email;
UPDATE customers SET email = 'ana@example.com' WHERE id = 4;
-- ERROR: duplicate key value violates unique constraint
ROLLBACK TO SAVEPOINT before_email;             -- city change kept
COMMIT;

-- Without the savepoint, any statement after the error fails with:
-- ERROR: current transaction is aborted, commands ignored until end
--        of transaction block

-- Expression index: case-insensitive email lookup
CREATE INDEX customers_email_lower_idx ON customers (lower(email));
SELECT id FROM customers WHERE lower(email) = 'ana@example.com';

-- Partial index: small, only the rows a hot query needs
CREATE INDEX orders_pending_idx ON orders (ordered_at) WHERE status = 'pending';
SELECT id FROM orders WHERE status = 'pending' ORDER BY ordered_at LIMIT 50;

-- Partial unique index: one pending order per customer
CREATE UNIQUE INDEX one_pending_per_customer
    ON orders (customer_id) WHERE status = 'pending';

-- Covering index enabling index-only scans
CREATE INDEX orders_cust_total_idx ON orders (customer_id) INCLUDE (total);
SELECT SUM(total) FROM orders WHERE customer_id = 2;

-- BRIN on a huge append-only table
CREATE INDEX events_created_brin ON events USING brin (created_at);

-- Unused indexes
SELECT indexrelname, idx_scan FROM pg_stat_user_indexes WHERE idx_scan = 0;

ALTER TABLE products ADD COLUMN attrs jsonb NOT NULL DEFAULT '{}';
UPDATE products SET attrs = '{"wireless": true, "layout": "US"}' WHERE id = 1;
UPDATE products SET attrs = '{"wireless": true, "dpi": 1600}'    WHERE id = 2;
UPDATE products SET attrs = '{"size_in": 27}'                    WHERE id = 3;

SELECT name, attrs ->> 'dpi' AS dpi FROM products WHERE attrs ? 'dpi';
--  Mouse | 1600

SELECT name FROM products WHERE attrs @> '{"wireless": true}';
--  Keyboard
--  Mouse

CREATE INDEX products_attrs_gin ON products USING gin (attrs jsonb_path_ops);

UPDATE products SET attrs = attrs || '{"color": "black"}' WHERE id = 2;

-- Build JSON for an API response
SELECT jsonb_build_object('customer', c.name,
                          'orders', jsonb_agg(o.id ORDER BY o.id)) AS doc
FROM customers c JOIN orders o ON o.customer_id = c.id
WHERE c.id = 1 GROUP BY c.name;
--  {"orders": [101, 102], "customer": "Ana"}

SELECT xmin, xmax, ctid, id, status FROM orders WHERE id = 102;
--  xmin | xmax | ctid  | id  | status
--   812 |    0 | (0,2) | 102 | pending

UPDATE orders SET status = 'shipped' WHERE id = 102;

SELECT xmin, xmax, ctid, id, status FROM orders WHERE id = 102;
--   815 |    0 | (0,6) | 102 | shipped    <- a new tuple at a new location
-- the old tuple at (0,2) is now dead, waiting for VACUUM

SELECT relname, n_live_tup, n_dead_tup, last_autovacuum
FROM pg_stat_user_tables WHERE relname = 'orders';

-- Who is holding back cleanup?
SELECT pid, state, xact_start, left(query, 40)
FROM pg_stat_activity
WHERE xact_start < now() - interval '10 minutes'
ORDER BY xact_start;

VACUUM (VERBOSE, ANALYZE) orders;

-- Lost update in READ COMMITTED (application-side arithmetic)
-- A: SELECT stock FROM products WHERE id = 3;    -- 5
-- B: SELECT stock FROM products WHERE id = 3;    -- 5
-- A: UPDATE products SET stock = 4 WHERE id = 3; COMMIT;
-- B: UPDATE products SET stock = 4 WHERE id = 3; COMMIT;   -- one sale lost

-- Safe: arithmetic in SQL re-reads the committed row
UPDATE products SET stock = stock - 1 WHERE id = 3 AND stock > 0;

-- Write skew prevented by SERIALIZABLE
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM shifts WHERE on_call AND day = '2026-03-15';  -- 2
UPDATE shifts SET on_call = false
WHERE doctor = 'alice' AND day = '2026-03-15';
COMMIT;
-- If bob ran the same transaction concurrently, one COMMIT fails with:
-- ERROR: could not serialize access due to read/write dependencies
--        among transactions   (SQLSTATE 40001) -> retry it

-- Job queue: each worker claims a different pending job
BEGIN;
SELECT id, payload FROM jobs
WHERE status = 'queued'
ORDER BY id
LIMIT 1
FOR UPDATE SKIP LOCKED;
-- ... do the work ...
UPDATE jobs SET status = 'done' WHERE id = 7;
COMMIT;

-- Deadlock: A locks order 101 then 102; B locks 102 then 101
-- ERROR: deadlock detected  (SQLSTATE 40P01)
-- Fix: always lock in the same order
SELECT id FROM orders WHERE id IN (101, 102) ORDER BY id FOR UPDATE;

-- Migrations: fail fast instead of queueing behind long transactions
SET lock_timeout = '3s';
ALTER TABLE orders ADD COLUMN note text;

-- Who blocks whom?
SELECT pid, pg_blocking_pids(pid) AS blocked_by, state, left(query, 50)
FROM pg_stat_activity
WHERE cardinality(pg_blocking_pids(pid)) > 0;

-- What the planner knows about a column
SELECT null_frac, n_distinct, most_common_vals, most_common_freqs
FROM pg_stats
WHERE tablename = 'orders' AND attname = 'status';
--  null_frac | n_distinct | most_common_vals            | most_common_freqs
--          0 |          3 | {shipped,pending,cancelled} | {0.81,0.15,0.04}

-- Refresh statistics after a bulk load
ANALYZE orders;

-- Skewed column: keep more detail
ALTER TABLE orders ALTER COLUMN customer_id SET STATISTICS 1000;

-- Correlated columns: teach the planner about the dependency
CREATE STATISTICS addr_city_country (dependencies, ndistinct, mcv)
    ON city, country FROM addresses;
ANALYZE addresses;

-- On SSD storage, random reads are not 4x sequential reads
ALTER SYSTEM SET random_page_cost = 1.1;
SELECT pg_reload_conf();

CREATE TABLE events (
    id         bigint GENERATED ALWAYS AS IDENTITY,
    created_at timestamptz NOT NULL,
    kind       text NOT NULL,
    payload    jsonb,
    PRIMARY KEY (id, created_at)        -- must include the partition key
) PARTITION BY RANGE (created_at);

CREATE TABLE events_2026_02 PARTITION OF events
    FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');
CREATE TABLE events_2026_03 PARTITION OF events
    FOR VALUES FROM ('2026-03-01') TO ('2026-04-01');

CREATE INDEX ON events (kind);          -- created on every partition

EXPLAIN SELECT count(*) FROM events WHERE created_at >= '2026-03-10';
--  Aggregate
--    ->  Seq Scan on events_2026_03 ...   (February partition pruned)

-- Retention: remove February without a giant DELETE
ALTER TABLE events DETACH PARTITION events_2026_02 CONCURRENTLY;
DROP TABLE events_2026_02;

-- Where is the WAL now?
SELECT pg_current_wal_lsn();               -- e.g. 0/3A01F2C8

-- On the primary: connected standbys and their lag
SELECT client_addr, state, sync_state, replay_lag
FROM pg_stat_replication;

-- Slots that are holding WAL back
SELECT slot_name, active,
       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained
FROM pg_replication_slots;

-- Relax durability for one bulk, low-value transaction only
BEGIN;
SET LOCAL synchronous_commit = off;
INSERT INTO page_views (path, viewed_at) VALUES ('/', now());
COMMIT;

-- Logical replication of selected tables
CREATE PUBLICATION shop_pub FOR TABLE customers, orders;
-- on the subscriber:
-- CREATE SUBSCRIPTION shop_sub
--     CONNECTION 'host=primary dbname=shop' PUBLICATION shop_pub;

concepts.body:
Tune in order of leverage, and measure before changing anything.

**1. Find what costs the most.** Enable the `pg_stat_statements` extension and sort by `total_exec_time`. A 2 ms query run 50,000 times a minute often matters more than a 3 second report run hourly. `log_min_duration_statement` writes each slow statement to PostgreSQL's log.

**2. Fix the query.** `EXPLAIN (ANALYZE, BUFFERS)` the top offenders. The usual findings:

- missing indexes, especially on foreign keys and on the leading columns of common filters;
- **N+1 queries**: app code fetches a list, then runs one more query for each item in it. Replace them with one join or `WHERE id = ANY($1)`;
- deep `OFFSET` paging: fetch the rows after the last one shown instead;
- functions on indexed columns, automatic conversions between types, or `OR` conditions that prevent index use;
- wrong row estimates: `ANALYZE`, extended statistics.

**3. Fix how the app uses the database.** Insert many rows per statement (multi-row `INSERT`, or `COPY`, the fastest way to load in bulk). Keep transactions short. Work out expensive totals ahead of time and store them, for example in materialized views (saved query results).

**4. Tune the server.** Typical starting points: `shared_buffers` about 25% of the server's memory; `effective_cache_size` 50-75% of memory (only a hint to the planner; it reserves nothing); `random_page_cost` around 1.1 on SSDs. `work_mem` applies **to each sort or hash step of each query**, so a high value for everyone, multiplied by hundreds of connections, uses up all the memory. Raise it only for one connection or one database user that runs heavy reports.

**5. Manage connections.** Each PostgreSQL connection is a separate running program on the server, using memory. Hundreds of mostly idle connections hurt. Put a **connection pool** such as PgBouncer in front: it keeps a few connections open and shares them, and the pool should stay near a small multiple of the server's processor cores.

**6. Keep maintenance healthy.** On big, busy tables, lower autovacuum's scale factor so it cleans up before wasted space (bloat) builds up. Set `statement_timeout` and `idle_in_transaction_session_timeout` as guard rails.

concepts.code:
-- needs shared_preload_libraries = 'pg_stat_statements'
CREATE EXTENSION IF NOT EXISTS pg_stat_statements;

SELECT calls,
       round(total_exec_time)        AS total_ms,
       round(mean_exec_time, 2)      AS mean_ms,
       left(query, 60)               AS query
FROM pg_stat_statements
ORDER BY total_exec_time DESC
LIMIT 5;

-- N+1 fix: one round trip instead of one per customer
SELECT customer_id, id, total FROM orders WHERE customer_id = ANY('{1,2,3}'::bigint[]);

-- More memory for one heavy report only (inside its transaction)
BEGIN; SET LOCAL work_mem = '256MB'; /* report query */ COMMIT;

-- Vacuum a large, hot table earlier (default scale factor is 0.2)
ALTER TABLE orders SET (autovacuum_vacuum_scale_factor = 0.02);

-- Guard rails
ALTER ROLE web_app SET statement_timeout = '5s';
ALTER ROLE web_app SET idle_in_transaction_session_timeout = '60s';
